use std::path::{Path, PathBuf};

use crate::locate::membership::{self, MembershipAuthority};
use crate::locate::LocateError;

pub fn find_workspace_root(start: &Path) -> Result<PathBuf, LocateError> {
    let canonical = dunce::canonicalize(start).unwrap_or_else(|_| start.to_path_buf());
    let mut current: &Path = &canonical;

    loop {
        if is_workspace_root(current)? {
            return Ok(current.to_path_buf());
        }
        match current.parent() {
            Some(parent) => current = parent,
            None => {
                return Err(LocateError::WorkspaceRootNotFound {
                    start: start.to_path_buf(),
                });
            }
        }
    }
}

fn is_workspace_root(dir: &Path) -> Result<bool, LocateError> {
    // Root discovery is itself an authority boundary. Do not duplicate a
    // permissive parser here: every membership reader distinguishes valid
    // absence from invalid configuration and propagates the latter.
    let cargo = membership::read_cargo_membership(dir)?;
    let npm = membership::read_npm_membership(dir)?;
    let python = membership::read_python_membership(dir)?;
    Ok(matches!(cargo, MembershipAuthority::Present(_))
        || matches!(npm, MembershipAuthority::Present(_))
        || matches!(python, MembershipAuthority::Present(_))
        || dir.join(".moon").is_dir())
}

